/* Local shim for Cloudflare's email-protection decoder. The application file is served
   untouched; this script only restores the addresses Cloudflare obfuscated at export time. */
(function(){function d(h){var k=parseInt(h.substr(0,2),16),s='';for(var i=2;i<h.length;i+=2)s+=String.fromCharCode(parseInt(h.substr(i,2),16)^k);try{return decodeURIComponent(escape(s))}catch(e){return s}}
function run(){document.querySelectorAll('.__cf_email__[data-cfemail]').forEach(function(a){var t=document.createTextNode(d(a.getAttribute('data-cfemail')));a.parentNode.replaceChild(t,a)});
document.querySelectorAll('a[href^="/cdn-cgi/l/email-protection#"]').forEach(function(a){a.href='mailto:'+d(a.getAttribute('href').split('#')[1])});}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',run);else run();})();
